import { PushNotificationAction } from '@aws-amplify/core/internals/utils';
import { IDENTIFY_USER_PATH, REGISTER_DEVICE_PATH, REMOVE_DEVICE_PATH, } from './resolveConfig';
import { signedFetch } from './signedFetch';
import { validateUserProfile } from './validateUserProfile';
/**
 * Sends a profile-only identify-user request. The backend derives `principalId`
 * from the SigV4 signer identity, so no `userId` is sent.
 *
 * @internal
 */
export const identifyUserInternal = async ({ userProfile, }) => {
    validateUserProfile(userProfile);
    await signedFetch(IDENTIFY_USER_PATH, { userProfile: userProfile ?? {} }, PushNotificationAction.IdentifyUser);
};
/**
 * Registers (upserts) a push device object. The wire shape nests the device
 * fields under `device` to match the backend `register-device` contract.
 *
 * @internal
 */
export const registerDeviceInternal = async (device) => {
    await signedFetch(REGISTER_DEVICE_PATH, { device }, PushNotificationAction.RegisterDevice);
};
/**
 * De-registers a push device object. The backend gates removal on the caller's
 * server-derived `principalId`.
 *
 * @internal
 */
export const removeDeviceInternal = async (deviceId) => {
    await signedFetch(REMOVE_DEVICE_PATH, { deviceId }, PushNotificationAction.RemoveDevice);
};
